import { type ModalStates, type WrapperDimension } from '@types/divi__modal';
import { type Help, type KeyboardShortcuts } from '@divi/types';
export type GroupedShortcuts = Record<string, Record<string, KeyboardShortcuts.Shortcut.Item>>;
export type ContainerProps<TAttributes = {
    currentVideoList?: string;
}> = ModalStates<TAttributes>;
export type VideoComponentProps = ContainerProps & {
    currentVideo: number;
    currentVideoList: string;
    overlayMode: boolean;
    dimension: WrapperDimension;
    groupedShortcuts: GroupedShortcuts;
    name: ModalStates['name'];
    setCurrentVideo: (currentVideo: number) => void;
    tab: ModalStates['tab'];
    videos: Help.Video.Registry;
};
export type PanelShortcutProps = {
    groupedShortcuts: GroupedShortcuts;
};
